package local.skyfamily;
import android.app.AlertDialog;import android.os.Handler;import android.text.InputFilter;import android.view.*;import android.widget.*;import java.util.*;
final class ReceiverNameSettings {
 static String savedName(PersonalActivity host){String value=host.prefs.getString("dlna.name","legacydash").trim();return value.isEmpty()?"legacydash":value;}
 static String advertisedName(){CastService service=CastService.instance;if(service==null)return null;TreeSet<String> names=new TreeSet<>();for(UpnpRenderer receiver:service.receivers.values())if(receiver.running)names.add(receiver.name);return names.isEmpty()?null:android.text.TextUtils.join(", ",names);}
 static String cardLabel(PersonalActivity host){String saved=savedName(host);if(!host.prefs.getBoolean("cast.persistent",true))return "DLNA receiver: "+saved+" / disabled";String advertised=advertisedName();if(advertised==null)return "DLNA receiver: "+saved+" / starting or network unavailable";return "DLNA receiver: "+advertised+(advertised.equals(saved)?"":"\nSaved name: "+saved+" / not yet advertised");}
 static String settingsLabel(PersonalActivity host){String saved=savedName(host),advertised=advertisedName();return "Saved name: "+saved+"\n"+(!host.prefs.getBoolean("cast.persistent",true)?"Receiver disabled":advertised==null?"Receiver starting or network unavailable":"Currently advertising: "+advertised);}
 static void add(PersonalActivity host){for(int i=0;i<host.body.getChildCount();i++)if("settings.dlna".equals(host.body.getChildAt(i).getTag()))return;int at=host.body.getChildCount();View toggle=null,heading=null,note=null;for(int i=0;i<host.body.getChildCount();i++){View child=host.body.getChildAt(i);if(child instanceof CheckBox&&"Receive DLNA casts automatically".contentEquals(((CheckBox)child).getText())){toggle=child;at=i;if(i>0&&host.body.getChildAt(i-1) instanceof TextView&&"Background casting".contentEquals(((TextView)host.body.getChildAt(i-1)).getText())){heading=host.body.getChildAt(i-1);at=i-1;}if(i+1<host.body.getChildCount()&&host.body.getChildAt(i+1) instanceof TextView&&((TextView)host.body.getChildAt(i+1)).getText().toString().startsWith("No receiving screen is required."))note=host.body.getChildAt(i+1);break;}}if(heading!=null)host.body.removeView(heading);if(toggle!=null)host.body.removeView(toggle);if(note!=null)host.body.removeView(note);LinearLayout group=host.paperPanel("DLNA receiver");group.setTag("settings.dlna");if(toggle!=null)group.addView(toggle,new LinearLayout.LayoutParams(-1,-2));group.addView(host.paperText("Device name",16,PaperActivity.INK));EditText input=new EditText(host);input.setHint("DLNA device name");input.setText(savedName(host));input.setTextSize(18);input.setSingleLine(true);input.setMinHeight(host.dp(54));input.setPadding(host.dp(14),host.dp(10),host.dp(14),host.dp(10));input.setBackground(host.controlBackground());input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(64)});group.addView(input,new LinearLayout.LayoutParams(-1,-2));ReceiverStatus status=new ReceiverStatus(host);group.addView(status,new LinearLayout.LayoutParams(-1,-2));group.addView(host.paperText("The Home casting card uses this same saved name. Applying a changed name ends a loaded cast after confirmation and refreshes discovery. Your sender may need to refresh its device list.",14,PaperActivity.MUTE));host.button("Save and apply DLNA name",()->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>64){host.toast("Enter a name with 1-64 characters");return;}for(int i=0;i<name.length();i++)if(Character.isISOControl(name.charAt(i))){host.toast("Name cannot contain control characters");return;}String advertised=advertisedName();boolean changed=!name.equals(savedName(host))||advertised!=null&&!name.equals(advertised);CastService service=CastService.instance;if(changed&&host.prefs.getBoolean("cast.persistent",true)&&service!=null&&service.active!=null&&!service.active.uri.isEmpty())new AlertDialog.Builder(host).setTitle("Apply receiver name?").setMessage("Applying the saved name ends the currently loaded cast and refreshes DLNA discovery.").setPositiveButton("Save and apply",(dialog,which)->apply(host,name,status,changed)).setNegativeButton("Cancel",null).show();else apply(host,name,status,changed);});View save=host.body.getChildAt(host.body.getChildCount()-1);host.body.removeView(save);group.addView(save);if(note!=null)group.addView(note,new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-1,-2);size.setMargins(0,host.dp(10),0,host.dp(12));host.body.addView(group,Math.min(at,host.body.getChildCount()),size);}
 static void apply(PersonalActivity host,String name,ReceiverStatus status,boolean changed){if(!host.prefs.edit().putString("dlna.name",name).commit()){status.error="Name NOT SAVED / check device storage";status.refresh();return;}status.error="";if(!host.prefs.getBoolean("cast.persistent",true)){status.refresh();return;}CastService service=CastService.instance;if(service==null){host.startCast();status.refresh();return;}if(!changed){status.refresh();return;}try{service.stopForExit();for(UpnpRenderer receiver:new ArrayList<UpnpRenderer>(service.receivers.values()))receiver.close();service.receivers.clear();service.active=null;service.nextScan=0;service.scan();status.refresh();}catch(Exception failure){status.error="Name saved / receiver refresh failed; disable and enable receiving";status.refresh();}}
 static final class ReceiverStatus extends TextView {final PersonalActivity host;final Handler timer=new Handler();String error="";final Runnable update=this::refresh;ReceiverStatus(PersonalActivity activity){super(activity);host=activity;setTextSize(15);setTextColor(host.inkColor(PaperActivity.MUTE));setPadding(0,host.dp(5),0,host.dp(8));setText(settingsLabel(host));}void refresh(){timer.removeCallbacks(update);setText(error.isEmpty()?settingsLabel(host):error);if(getWindowToken()!=null&&getWindowVisibility()==VISIBLE)timer.postDelayed(update,2000);}protected void onAttachedToWindow(){super.onAttachedToWindow();refresh();}protected void onDetachedFromWindow(){timer.removeCallbacks(update);super.onDetachedFromWindow();}protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(timer!=null){timer.removeCallbacks(update);if(visibility==VISIBLE&&host!=null)timer.post(update);}}}
}
